import{Ba as d,Qa as n,Ra as t,Sa as r,ab as e}from"./chunk-56ESLHRL.js";var s=class u{constructor(){}ngOnInit(){}static \u0275fac=function(i){return new(i||u)};static \u0275cmp=d({type:u,selectors:[["app-privacy"]],decls:165,vars:0,consts:[[1,"container"],[1,"row"],[1,"col-12","col-md-8","offset-md-2"],["href","https://www.e-recht24.de"]],template:function(i,E){i&1&&(n(0,"section")(1,"div",0)(2,"div",1)(3,"div",2)(4,"h2"),e(5,"Datenschutzerkl\xE4rung"),t(),n(6,"h3"),e(7,"1. Datenschutz auf einen Blick"),t(),n(8,"h4"),e(9,"Allgemeine Hinweise"),t(),n(10,"p"),e(11,"Die folgenden Hinweise geben einen einfachen \xDCberblick dar\xFCber, was mit Ihren personenbezogenen Daten passiert, wenn Sie diese Website besuchen. Personenbezogene Daten sind alle Daten, mit denen Sie pers\xF6nlich identifiziert werden k\xF6nnen. Ausf\xFChrliche Informationen zum Thema Datenschutz entnehmen Sie unserer unter diesem Text aufgef\xFChrten Datenschutzerkl\xE4rung."),t(),n(12,"h4"),e(13,"Datenerfassung auf dieser Website"),t(),n(14,"h5"),e(15,"Wer ist verantwortlich f\xFCr die Datenerfassung auf dieser Website?"),t(),n(16,"p"),e(17,"Die Datenverarbeitung auf dieser Website erfolgt durch den Websitebetreiber. Dessen Kontaktdaten k\xF6nnen Sie dem Abschnitt \u201EHinweis zur Verantwortlichen Stelle\u201C in dieser Datenschutzerkl\xE4rung entnehmen."),t(),n(18,"h5"),e(19,"Wie erfassen wir Ihre Daten?"),t(),n(20,"p"),e(21,"Ihre Daten werden zum einen dadurch erhoben, dass Sie uns diese mitteilen. Hierbei kann es sich z.\xA0B. um Daten handeln, die Sie in ein Kontaktformular eingeben."),t(),n(22,"p"),e(23,"Andere Daten werden automatisch oder nach Ihrer Einwilligung beim Besuch der Website durch unsere IT-Systeme erfasst. Das sind vor allem technische Daten (z.\xA0B. Internetbrowser, Betriebssystem oder Uhrzeit des Seitenaufrufs). Die Erfassung dieser Daten erfolgt automatisch, sobald Sie diese Website betreten."),t(),n(24,"h5"),e(25,"Wof\xFCr nutzen wir Ihre Daten?"),t(),n(26,"p"),e(27,"Ein Teil der Daten wird erhoben, um eine fehlerfreie Bereitstellung der Website zu gew\xE4hrleisten. Andere Daten k\xF6nnen zur Analyse Ihres Nutzerverhaltens verwendet werden."),t(),n(28,"h5"),e(29,"Welche Rechte haben Sie bez\xFCglich Ihrer Daten?"),t(),n(30,"p"),e(31,"Sie haben jederzeit das Recht, unentgeltlich Auskunft \xFCber Herkunft, Empf\xE4nger und Zweck Ihrer gespeicherten personenbezogenen Daten zu erhalten. Sie haben au\xDFerdem ein Recht, die Berichtigung oder L\xF6schung dieser Daten zu verlangen. Wenn Sie eine Einwilligung zur Datenverarbeitung erteilt haben, k\xF6nnen Sie diese Einwilligung jederzeit f\xFCr die Zukunft widerrufen. Au\xDFerdem haben Sie das Recht, unter bestimmten Umst\xE4nden die Einschr\xE4nkung der Verarbeitung Ihrer personenbezogenen Daten zu verlangen. Des Weiteren steht Ihnen ein Beschwerderecht bei der zust\xE4ndigen Aufsichtsbeh\xF6rde zu."),t(),n(32,"p"),e(33,"Hierzu sowie zu weiteren Fragen zum Thema Datenschutz k\xF6nnen Sie sich jederzeit an uns wenden."),t(),n(34,"h4"),e(35,"Analyse-Tools und Tools von Drittanbietern"),t(),n(36,"p"),e(37,"Beim Besuch dieser Website kann Ihr Surf-Verhalten statistisch ausgewertet werden. Das geschieht vor allem mit sogenannten Analyseprogrammen."),t(),n(38,"p"),e(39,"Detaillierte Informationen zu diesen Analyseprogrammen finden Sie in der folgenden Datenschutzerkl\xE4rung."),t(),n(40,"h3"),e(41,"2. Hosting"),t(),n(42,"h4"),e(43,"Externes Hosting"),t(),n(44,"p"),e(45,"Diese Website wird bei einem externen Dienstleister gehostet (Hoster). Die personenbezogenen Daten, die auf dieser Website erfasst werden, werden auf den Servern des Hosters gespeichert. Hierbei kann es sich v. a. um IP-Adressen, Kontaktanfragen, Meta- und Kommunikationsdaten, Vertragsdaten, Kontaktdaten, Namen, Websitezugriffe und sonstige Daten, die \xFCber eine Website generiert werden, handeln."),t(),n(46,"p"),e(47," Der Einsatz des Hosters erfolgt zum Zwecke der Vertragserf\xFCllung gegen\xFCber unseren potenziellen und bestehenden Kunden (Art. 6 Abs. 1 lit. b DSGVO) und im Interesse einer sicheren, schnellen und effizienten Bereitstellung unseres Online-Angebots durch einen professionellen Anbieter (Art. 6 Abs. 1 lit. f DSGVO)."),t(),n(48,"p"),e(49,"Unser Hoster wird Ihre Daten nur insoweit verarbeiten, wie dies zur Erf\xFCllung seiner Leistungspflichten erforderlich ist und unsere Weisungen in Bezug auf diese Daten befolgen."),t(),n(50,"p"),e(51,"Wir setzen folgenden Hoster ein:"),t(),n(52,"p"),e(53,"dogado GmbH"),r(54,"br"),e(55," Antonio-Segni-Stra\xDFe 11"),r(56,"br"),e(57," 44263 Dortmund"),t(),n(58,"h5"),e(59,"Auftragsverarbeitung"),t(),n(60,"p"),e(61,"Wir haben einen Vertrag \xFCber Auftragsverarbeitung (AVV) mit dem oben genannten Anbieter geschlossen. Hierbei handelt es sich um einen datenschutzrechtlich vorgeschriebenen Vertrag, der gew\xE4hrleistet, dass dieser die personenbezogenen Daten unserer Websitebesucher nur nach unseren Weisungen und unter Einhaltung der DSGVO verarbeitet."),t(),n(62,"h3"),e(63,"3. Allgemeine Hinweise und Pflichtinformationen"),t(),n(64,"h4"),e(65,"Datenschutz"),t(),n(66,"p"),e(67,"Die Betreiber dieser Seiten nehmen den Schutz Ihrer pers\xF6nlichen Daten sehr ernst. Wir behandeln Ihre personenbezogenen Daten vertraulich und entsprechend den gesetzlichen Datenschutzvorschriften sowie dieser Datenschutzerkl\xE4rung."),t(),n(68,"p"),e(69,"Wenn Sie diese Website benutzen, werden verschiedene personenbezogene Daten erhoben. Personenbezogene Daten sind Daten, mit denen Sie pers\xF6nlich identifiziert werden k\xF6nnen. Die vorliegende Datenschutzerkl\xE4rung erl\xE4utert, welche Daten wir erheben und wof\xFCr wir sie nutzen. Sie erl\xE4utert auch, wie und zu welchem Zweck das geschieht."),t(),n(70,"p"),e(71,"Wir weisen darauf hin, dass die Daten\xFCbertragung im Internet (z.\xA0B. bei der Kommunikation per E-Mail) Sicherheitsl\xFCcken aufweisen kann. Ein l\xFCckenloser Schutz der Daten vor dem Zugriff durch Dritte ist nicht m\xF6glich."),t(),n(72,"h4"),e(73,"Hinweis zur verantwortlichen Stelle"),t(),n(74,"p"),e(75,"Die verantwortliche Stelle f\xFCr die Datenverarbeitung auf dieser Website ist:"),t(),n(76,"p"),e(77,"Sebastian Fuss, Butzbacher Stra\xDFe 60, 60389 Frankfurt"),t(),n(78,"p"),e(79,"E-Mail: privacy@sebastian-fuss.de"),t(),n(80,"p"),e(81,"Verantwortliche Stelle ist die nat\xFCrliche oder juristische Person, die allein oder gemeinsam mit anderen \xFCber die Zwecke und Mittel der Verarbeitung von personenbezogenen Daten (z.\xA0B. Namen, E-Mail-Adressen o. \xC4.) entscheidet."),t(),n(82,"h4"),e(83,"Speicherdauer"),t(),n(84,"p"),e(85,"Soweit innerhalb dieser Datenschutzerkl\xE4rung keine speziellere Speicherdauer genannt wurde, verbleiben Ihre personenbezogenen Daten bei uns, bis der Zweck f\xFCr die Datenverarbeitung entf\xE4llt. Wenn Sie ein berechtigtes L\xF6schersuchen geltend machen oder eine Einwilligung zur Datenverarbeitung widerrufen, werden Ihre Daten gel\xF6scht, sofern wir keine anderen rechtlich zul\xE4ssigen Gr\xFCnde f\xFCr die Speicherung Ihrer personenbezogenen Daten haben (z.\xA0B. steuer- oder handelsrechtliche Aufbewahrungsfristen); im letztgenannten Fall erfolgt die L\xF6schung nach Fortfall dieser Gr\xFCnde."),t(),n(86,"h4"),e(87,"Widerruf Ihrer Einwilligung zur Datenverarbeitung"),t(),n(88,"p"),e(89,"Viele Datenverarbeitungsvorg\xE4nge sind nur mit Ihrer ausdr\xFCcklichen Einwilligung m\xF6glich. Sie k\xF6nnen eine bereits erteilte Einwilligung jederzeit widerrufen. Die Rechtm\xE4\xDFigkeit der bis zum Widerruf erfolgten Datenverarbeitung bleibt vom Widerruf unber\xFChrt."),t(),n(90,"h4"),e(91,"Widerspruchsrecht gegen die Datenerhebung in besonderen F\xE4llen sowie gegen Direktwerbung (Art. 21 DSGVO)"),t(),n(92,"p"),e(93,"WENN DIE DATENVERARBEITUNG AUF GRUNDLAGE VON ART. 6 ABS. 1 LIT. E ODER F DSGVO ERFOLGT, HABEN SIE JEDERZEIT DAS RECHT, AUS GR\xDCNDEN, DIE SICH AUS IHRER BESONDEREN SITUATION ERGEBEN, GEGEN DIE VERARBEITUNG IHRER PERSONENBEZOGENEN DATEN WIDERSPRUCH EINZULEGEN; DIES GILT AUCH F\xDCR EIN AUF DIESE BESTIMMUNGEN GEST\xDCTZTES PROFILING. DIE JEWEILIGE RECHTSGRUNDLAGE, AUF DENEN EINE VERARBEITUNG BERUHT, ENTNEHMEN SIE DIESER DATENSCHUTZERKL\xC4RUNG. WENN SIE WIDERSPRUCH EINLEGEN, WERDEN WIR IHRE BETROFFENEN PERSONENBEZOGENEN DATEN NICHT MEHR VERARBEITEN, ES SEI DENN, WIR K\xD6NNEN ZWINGENDE SCHUTZW\xDCRDIGE GR\xDCNDE F\xDCR DIE VERARBEITUNG NACHWEISEN, DIE IHRE INTERESSEN, RECHTE UND FREIHEITEN \xDCBERWIEGEN ODER DIE VERARBEITUNG DIENT DER GELTENDMACHUNG, AUS\xDCBUNG ODER VERTEIDIGUNG VON RECHTSANSPR\xDCCHEN (WIDERSPRUCH NACH ART. 21 ABS. 1 DSGVO)."),t(),n(94,"p"),e(95,"WERDEN IHRE PERSONENBEZOGENEN DATEN VERARBEITET, UM DIREKTWERBUNG ZU BETREIBEN, SO HABEN SIE DAS RECHT, JEDERZEIT WIDERSPRUCH GEGEN DIE VERARBEITUNG SIE BETREFFENDER PERSONENBEZOGENER DATEN ZUM ZWECKE DERARTIGER WERBUNG EINZULEGEN; DIES GILT AUCH F\xDCR DAS PROFILING, SOWEIT ES MIT SOLCHER DIREKTWERBUNG IN VERBINDUNG STEHT. WENN SIE WIDERSPRECHEN, WERDEN IHRE PERSONENBEZOGENEN DATEN ANSCHLIESSEND NICHT MEHR ZUM ZWECKE DER DIREKTWERBUNG VERWENDET (WIDERSPRUCH NACH ART. 21 ABS. 2 DSGVO)."),t(),n(96,"h4"),e(97,"Beschwerderecht bei der zust\xE4ndigen Aufsichtsbeh\xF6rde"),t(),n(98,"p"),e(99,"Im Falle von Verst\xF6\xDFen gegen die DSGVO steht den Betroffenen ein Beschwerderecht bei einer Aufsichtsbeh\xF6rde, insbesondere in dem Mitgliedstaat ihres gew\xF6hnlichen Aufenthalts, ihres Arbeitsplatzes oder des Orts des mutma\xDFlichen Versto\xDFes zu. Das Beschwerderecht besteht unbeschadet anderweitiger verwaltungsrechtlicher oder gerichtlicher Rechtsbehelfe."),t(),n(100,"h4"),e(101,"Recht auf Daten\xFCbertragbarkeit"),t(),n(102,"p"),e(103,"Sie haben das Recht, Daten, die wir auf Grundlage Ihrer Einwilligung oder in Erf\xFCllung eines Vertrags automatisiert verarbeiten, an sich oder an einen Dritten in einem g\xE4ngigen, maschinenlesbaren Format aush\xE4ndigen zu lassen. Sofern Sie die direkte \xDCbertragung der Daten an einen anderen Verantwortlichen verlangen, erfolgt dies nur, soweit es technisch machbar ist."),t(),n(104,"h4"),e(105,"SSL- bzw. TLS-Verschl\xFCsselung"),t(),n(106,"p"),e(107,"Diese Seite nutzt aus Sicherheitsgr\xFCnden und zum Schutz der \xDCbertragung vertraulicher Inhalte, wie zum Beispiel Bestellungen oder Anfragen, die Sie an uns als Seitenbetreiber senden, eine SSL- bzw. TLS-Verschl\xFCsselung. Eine verschl\xFCsselte Verbindung erkennen Sie daran, dass die Adresszeile des Browsers von \u201Ehttp://\u201C auf \u201Ehttps://\u201C wechselt und an dem Schloss-Symbol in Ihrer Browserzeile."),t(),n(108,"p"),e(109,"Wenn die SSL- bzw. TLS-Verschl\xFCsselung aktiviert ist, k\xF6nnen die Daten, die Sie an uns \xFCbermitteln, nicht von Dritten mitgelesen werden."),t(),n(110,"h4"),e(111,"Auskunft, L\xF6schung und Berichtigung"),t(),n(112,"p"),e(113,"Sie haben im Rahmen der geltenden gesetzlichen Bestimmungen jederzeit das Recht auf unentgeltliche Auskunft \xFCber Ihre gespeicherten personenbezogenen Daten, deren Herkunft und Empf\xE4nger und den Zweck der Datenverarbeitung und ggf. ein Recht auf Berichtigung oder L\xF6schung dieser Daten. Hierzu sowie zu weiteren Fragen zum Thema personenbezogene Daten k\xF6nnen Sie sich jederzeit an uns wenden."),t(),n(114,"h4"),e(115,"Recht auf Einschr\xE4nkung der Verarbeitung"),t(),n(116,"p"),e(117,"Sie haben das Recht, die Einschr\xE4nkung der Verarbeitung Ihrer personenbezogenen Daten zu verlangen. Hierzu k\xF6nnen Sie sich jederzeit an uns wenden. Das Recht auf Einschr\xE4nkung der Verarbeitung besteht in folgenden F\xE4llen:"),t(),n(118,"ul")(119,"li"),e(120,"Wenn Sie die Richtigkeit Ihrer bei uns gespeicherten personenbezogenen Daten bestreiten, ben\xF6tigen wir in der Regel Zeit, um dies zu \xFCberpr\xFCfen. F\xFCr die Dauer der Pr\xFCfung haben Sie das Recht, die Einschr\xE4nkung der Verarbeitung Ihrer personenbezogenen Daten zu verlangen. "),t(),n(121,"li"),e(122,"Wenn die Verarbeitung Ihrer personenbezogenen Daten unrechtm\xE4\xDFig geschah/geschieht, k\xF6nnen Sie statt der L\xF6schung die Einschr\xE4nkung der Datenverarbeitung verlangen. "),t(),n(123,"li"),e(124,"Wenn wir Ihre personenbezogenen Daten nicht mehr ben\xF6tigen, Sie sie jedoch zur Aus\xFCbung, Verteidigung oder Geltendmachung von Rechtsanspr\xFCchen ben\xF6tigen, haben Sie das Recht, statt der L\xF6schung die Einschr\xE4nkung der Verarbeitung Ihrer personenbezogenen Daten zu verlangen. "),t(),n(125,"li"),e(126,"Wenn Sie einen Widerspruch nach Art. 21 Abs. 1 DSGVO eingelegt haben, muss eine Abw\xE4gung zwischen Ihren und unseren Interessen vorgenommen werden. Solange noch nicht feststeht, wessen Interessen \xFCberwiegen, haben Sie das Recht, die Einschr\xE4nkung der Verarbeitung Ihrer personenbezogenen Daten zu verlangen. "),t()(),n(127,"p"),e(128,"Wenn Sie die Verarbeitung Ihrer personenbezogenen Daten eingeschr\xE4nkt haben, d\xFCrfen diese Daten \u2013 von ihrer Speicherung abgesehen \u2013 nur mit Ihrer Einwilligung oder zur Geltendmachung, Aus\xFCbung oder Verteidigung von Rechtsanspr\xFCchen oder zum Schutz der Rechte einer anderen nat\xFCrlichen oder juristischen Person oder aus Gr\xFCnden eines wichtigen \xF6ffentlichen Interesses der Europ\xE4ischen Union oder eines Mitgliedstaats verarbeitet werden."),t(),n(129,"h3"),e(130,"4. Datenerfassung auf dieser Website"),t(),n(131,"h4"),e(132,"Cookies"),t(),n(133,"p"),e(134,"Unsere Internetseiten verwenden so genannte \u201ECookies\u201C. Cookies sind kleine Textdateien und richten auf Ihrem Endger\xE4t keinen Schaden an. Sie werden entweder vor\xFCbergehend f\xFCr die Dauer einer Sitzung (Session-Cookies) oder dauerhaft (permanente Cookies) auf Ihrem Endger\xE4t gespeichert. Session-Cookies werden nach Ende Ihres Besuchs automatisch gel\xF6scht. Permanente Cookies bleiben auf Ihrem Endger\xE4t gespeichert, bis Sie diese selbst l\xF6schen\xA0oder eine automatische L\xF6schung durch Ihren Webbrowser erfolgt."),t(),n(135,"p"),e(136,"Teilweise k\xF6nnen auch Cookies von Drittunternehmen auf Ihrem Endger\xE4t gespeichert werden, wenn Sie unsere Seite betreten (Third-Party-Cookies). Diese erm\xF6glichen uns oder Ihnen die Nutzung bestimmter Dienstleistungen des Drittunternehmens (z.\xA0B. Cookies zur Abwicklung von Zahlungsdienstleistungen)."),t(),n(137,"p"),e(138," Cookies haben verschiedene Funktionen. Zahlreiche Cookies sind technisch notwendig, da bestimmte Websitefunktionen ohne diese nicht funktionieren w\xFCrden (z.\xA0B. die Warenkorbfunktion oder die Anzeige von Videos). Andere Cookies dienen dazu, das Nutzerverhalten auszuwerten\xA0oder Werbung anzuzeigen."),t(),n(139,"p"),e(140,"Cookies, die zur Durchf\xFChrung des elektronischen Kommunikationsvorgangs (notwendige Cookies) oder zur Bereitstellung bestimmter, von Ihnen erw\xFCnschter Funktionen (funktionale Cookies, z.\xA0B. f\xFCr die Warenkorbfunktion) oder zur Optimierung der Website (z.\xA0B. Cookies zur Messung des Webpublikums) erforderlich sind, werden auf Grundlage von Art. 6 Abs. 1 lit. f DSGVO gespeichert, sofern keine andere Rechtsgrundlage angegeben wird. Der Websitebetreiber hat ein berechtigtes Interesse an der Speicherung von Cookies zur technisch fehlerfreien und optimierten Bereitstellung seiner Dienste. Sofern eine Einwilligung zur Speicherung von Cookies abgefragt wurde, erfolgt die Speicherung der betreffenden Cookies ausschlie\xDFlich auf Grundlage dieser Einwilligung (Art. 6 Abs. 1 lit. a DSGVO); die Einwilligung ist jederzeit widerrufbar."),t(),n(141,"p"),e(142,"Sie k\xF6nnen Ihren Browser so einstellen, dass Sie \xFCber das Setzen von Cookies informiert werden und Cookies nur im Einzelfall erlauben, die Annahme von Cookies f\xFCr bestimmte F\xE4lle oder generell ausschlie\xDFen sowie das automatische L\xF6schen der Cookies beim Schlie\xDFen des Browsers aktivieren. Bei der Deaktivierung von Cookies kann die Funktionalit\xE4t dieser Website eingeschr\xE4nkt sein."),t(),n(143,"p"),e(144,"Soweit Cookies von Drittunternehmen oder zu Analysezwecken eingesetzt werden, werden wir Sie hier\xFCber im Rahmen dieser Datenschutzerkl\xE4rung gesondert informieren und ggf. eine Einwilligung abfragen."),t(),n(145,"h4"),e(146,"Kontaktformular"),t(),n(147,"p"),e(148,"Wenn Sie uns per Kontaktformular Anfragen zukommen lassen, werden Ihre Angaben aus dem Anfrageformular inklusive der von Ihnen dort angegebenen Kontaktdaten zwecks Bearbeitung der Anfrage und f\xFCr den Fall von Anschlussfragen bei uns gespeichert. Diese Daten geben wir nicht ohne Ihre Einwilligung weiter."),t(),n(149,"p"),e(150,"Die Verarbeitung dieser Daten erfolgt auf Grundlage von Art. 6 Abs. 1 lit. b DSGVO, sofern Ihre Anfrage mit der Erf\xFCllung eines Vertrags zusammenh\xE4ngt oder zur Durchf\xFChrung vorvertraglicher Ma\xDFnahmen erforderlich ist. In allen \xFCbrigen F\xE4llen beruht die Verarbeitung auf unserem berechtigten Interesse an der effektiven Bearbeitung der an uns gerichteten Anfragen (Art. 6 Abs. 1 lit. f DSGVO) oder auf Ihrer Einwilligung (Art. 6 Abs. 1 lit. a DSGVO) sofern diese abgefragt wurde."),t(),n(151,"p"),e(152,"Die von Ihnen im Kontaktformular eingegebenen Daten verbleiben bei uns, bis Sie uns zur L\xF6schung auffordern, Ihre Einwilligung zur Speicherung widerrufen oder der Zweck f\xFCr die Datenspeicherung entf\xE4llt (z.\xA0B. nach abgeschlossener Bearbeitung Ihrer Anfrage). Zwingende gesetzliche Bestimmungen \u2013 insbesondere Aufbewahrungsfristen \u2013 bleiben unber\xFChrt."),t(),n(153,"h4"),e(154,"Anfrage per E-Mail, Telefon oder Telefax"),t(),n(155,"p"),e(156,"Wenn Sie uns per E-Mail, Telefon oder Telefax kontaktieren, wird Ihre Anfrage inklusive aller daraus hervorgehenden personenbezogenen Daten (Name, Anfrage) zum Zwecke der Bearbeitung Ihres Anliegens bei uns gespeichert und verarbeitet. Diese Daten geben wir nicht ohne Ihre Einwilligung weiter."),t(),n(157,"p"),e(158,"Die Verarbeitung dieser Daten erfolgt auf Grundlage von Art. 6 Abs. 1 lit. b DSGVO, sofern Ihre Anfrage mit der Erf\xFCllung eines Vertrags zusammenh\xE4ngt oder zur Durchf\xFChrung vorvertraglicher Ma\xDFnahmen erforderlich ist. In allen \xFCbrigen F\xE4llen beruht die Verarbeitung auf unserem berechtigten Interesse an der effektiven Bearbeitung der an uns gerichteten Anfragen (Art. 6 Abs. 1 lit. f DSGVO) oder auf Ihrer Einwilligung (Art. 6 Abs. 1 lit. a DSGVO) sofern diese abgefragt wurde."),t(),n(159,"p"),e(160,"Die von Ihnen an uns per Kontaktanfragen \xFCbersandten Daten verbleiben bei uns, bis Sie uns zur L\xF6schung auffordern, Ihre Einwilligung zur Speicherung widerrufen oder der Zweck f\xFCr die Datenspeicherung entf\xE4llt (z.\xA0B. nach abgeschlossener Bearbeitung Ihres Anliegens). Zwingende gesetzliche Bestimmungen \u2013 insbesondere gesetzliche Aufbewahrungsfristen \u2013 bleiben unber\xFChrt."),t(),n(161,"p"),e(162,"Quelle: "),n(163,"a",3),e(164,"https://www.e-recht24.de"),t()()()()()())},encapsulation:2})};export{s as PrivacyComponent};
